#!/usr/bin/env bash
# Some portions generated by Codex. Route/correctness smoke, not timings.
set -euo pipefail
cd "$(dirname "$0")/../../.."
exec 9>experiments/overlay/native-benchmark.lock; flock 9
JAVA=../toolchain/jdk-25.0.5+8/bin/java
mapfile -t FLAGS < experiments/threadlocal-audit/best-flags.txt
FLAGS+=(-Drdf4j.lmdb.queryMemory.perQueryMaxBytes=671088640)
for arm in a b c d; do
 for regime in regular interpreted janino; do
  "$JAVA" --enable-native-access=ALL-UNNAMED -Xms1g -Xmx3g "${FLAGS[@]}" -Daudit.regime="$regime" -Doverlay.benchmark.warmups=0 \
   -cp "experiments/threadlocal-audit/source-pull/smoke-harness:$(cat experiments/threadlocal-audit/source-pull/cp-$arm.txt)" \
   org.eclipse.rdf4j.sail.lmdb.evaluation.ThreadLocalQueryBenchmark 2 10 1 true \
   > "experiments/threadlocal-audit/source-pull/smoke-$regime-$arm.log" 2>&1
 done
done
